ASNParser::ASNParser(TokenStream *input) : ASNParser(input, antlr4::atn::ParserATNSimulatorOptions()) {}

ASNParser::ASNParser(TokenStream *input, const antlr4::atn::ParserATNSimulatorOptions &options) : Parser(input) {
  ASNParser::initialize();
  _interpreter = new atn::ParserATNSimulator(this, *asnParserStaticData->atn, asnParserStaticData->decisionToDFA, asnParserStaticData->sharedContextCache, options);
}

ASNParser::~ASNParser() {
  delete _interpreter;
}

const atn::ATN& ASNParser::getATN() const {
  return *asnParserStaticData->atn;
}

